   208→    /**
   209→     * Score all network interfaces for Pro DJ Link suitability.
   210→     * Returns list sorted by score descending.
   211→     */
   212→    private List<Map<String, Object>> scoreAllInterfaces() throws SocketException {
   213→        List<Map<String, Object>> candidates = new ArrayList<>();
   214→
   215→        Enumeration<NetworkInterface> interfaces = NetworkInterface.getNetworkInterfaces();
   216→        if (interfaces == null) return candidates;
   217→
   218→        while (interfaces.hasMoreElements()) {
   219→            NetworkInterface iface = interfaces.nextElement();
   220→
   221→            // Filter out loopback and down interfaces
   222→            if (iface.isLoopback() || !iface.isUp()) continue;
   223→
   224→            // Filter out virtual interfaces
   225→            String name = iface.getName().toLowerCase();
   226→            boolean isVirtual = VIRTUAL_PREFIXES.stream().anyMatch(name::startsWith);
   227→            if (isVirtual) continue;
   228→
   229→            // Get the first non-loopback IPv4 address
   230→            String address = null;
   231→            boolean hasLinkLocal = false;
   232→            boolean hasPrivate = false;
   233→            for (Enumeration<InetAddress> addrs = iface.getInetAddresses(); addrs.hasMoreElements(); ) {
   234→                InetAddress addr = addrs.nextElement();
   235→                if (addr instanceof Inet4Address && !addr.isLoopbackAddress()) {
   236→                    if (address == null) address = addr.getHostAddress();
   237→                    if (addr.isLinkLocalAddress()) hasLinkLocal = true;
   238→                    String ip = addr.getHostAddress();
   239→                    if (ip.startsWith("10.") || ip.startsWith("192.168.")) hasPrivate = true;
   240→                }
   241→            }
   242→
   243→            if (address == null) continue; // No usable IPv4 address
   244→
   245→            // Score the interface
   246→            int score = 0;
   247→            String type = "unknown";
   248→
   249→            // +10 for link-local (169.254.x.x) — Pro DJ Link auto-config range
   250→            if (hasLinkLocal) score += 10;
   251→
   252→            // Classify interface type
   253→            if (isWiredEthernet(iface)) {
   254→                type = "ethernet";
   255→                score += 5;
   256→            } else if (isWifi(iface)) {
   257→                type = "wifi";
   258→                score -= 5;
   259→            } else if (name.startsWith("utun") || name.startsWith("tun") || name.startsWith("tap")) {
   260→                type = "vpn";
   261→                score -= 10;
   262→            } else {
   263→                type = "other";
   264→            }
   265→
   266→            // +3 for private ranges (common manual DJ network configs)
   267→            if (hasPrivate) score += 3;
   268→
   269→            Map<String, Object> candidate = new LinkedHashMap<>();
   270→            candidate.put("name", iface.getName());
   271→            candidate.put("address", address);
   272→            candidate.put("type", type);
   273→            candidate.put("score", score);
   274→            candidate.put("selected", false); // will be set to true for the chosen one
   275→            candidates.add(candidate);
   276→        }
   277→
   278→        // Sort by score descending
   279→        candidates.sort((a, b) -> ((Integer) b.get("score")).compareTo((Integer) a.get("score")));
   280→
   281→        // Mark the top candidate as selected
   282→        if (!candidates.isEmpty()) {
   283→            candidates.get(0).put("selected", true);
   284→        }
   285→
   286→        return candidates;
   287→    }
